  CONSTRAINT quote_messages_quote_request_id_fkey FOREIGN KEY (quote_request_id) REFERENCES quote_requests(id) ON DELETE CASCADE,
  CONSTRAINT quote_messages_sender_id_fkey FOREIGN KEY (sender_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TRIGGER trg_quote_message_insert AFTER INSERT ON public.quote_messages FOR EACH ROW EXECUTE FUNCTION update_quote_request_on_message();

CREATE TABLE quote_offer_lines (
