  CONSTRAINT quote_offer_lines_producer_id_fkey FOREIGN KEY (producer_id) REFERENCES producers(id),
  CONSTRAINT quote_offer_lines_product_id_fkey FOREIGN KEY (product_id) REFERENCES products(id)
);
CREATE INDEX quote_offer_lines_offer_idx ON public.quote_offer_lines USING btree (offer_id);

CREATE TABLE quote_offers (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
  quote_request_id uuid NOT NULL,
  admin_id uuid NOT NULL,
  subtotal numeric(12,2) NOT NULL,
  delivery_fee numeric(12,2) DEFAULT 0 NOT NULL,
  discount_amount numeric(12,2) DEFAULT 0 NOT NULL,
  total numeric(12,2) NOT NULL,
  currency character(3) DEFAULT 'NGN'::bpchar NOT NULL,
  lead_time_hours integer NOT NULL,
  delivery_estimate_date date,
  payment_terms text DEFAULT '50% upfront, 50% on delivery'::text,
  terms text,
  expires_at timestamp with time zone NOT NULL,
  status text DEFAULT 'draft'::text NOT NULL,
  sent_at timestamp with time zone,
  responded_at timestamp with time zone,
  superseded_by_offer_id uuid,
  created_at timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT quote_offers_pkey PRIMARY KEY (id),
  CONSTRAINT quote_offers_admin_id_fkey FOREIGN KEY (admin_id) REFERENCES users(id),
  CONSTRAINT quote_offers_superseded_by_offer_id_fkey FOREIGN KEY (superseded_by_offer_id) REFERENCES quote_offers(id),
  CONSTRAINT quote_offers_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'sent'::text, 'accepted'::text, 'rejected'::text, 'expired'::text, 'superseded'::text])))
);
CREATE INDEX quote_offers_active_idx ON public.quote_offers USING btree (status, expires_at) WHERE (status = 'sent'::text);
CREATE INDEX quote_offers_request_idx ON public.quote_offers USING btree (quote_request_id, created_at DESC);

CREATE TABLE quote_request_items (
  id uuid DEFAULT gen_random_uuid() NOT NULL,
